Node* closest_node = nullptr;
float min_dist_sq = std::numeric_limits<float>::max();

for (auto it = graph.nodes.begin(); it != graph.nodes.end(); ++it) {
    Node* node = it->second;

    // Check if the node is part of a footway road
    bool is_footway = false;
    for (const auto& edge : node->edges) {
        if (edge.road_type == RoadType::FOOTWAY) {
            is_footway = true;
            break;
        }
    }

    if (is_footway) continue;

    float dx = node->x - x;
    float dy = node->y - y;
    float dist_sq = dx * dx + dy * dy;

    if (dist_sq < min_dist_sq) {
        min_dist_sq = dist_sq;
        closest_node = node;
    }
}

return closest_node;
